# firmware/auth_controller.rb
# IoT Device Authentication Module v2.3.1
# Handles device-to-cloud authentication with rate limiting

require 'digest'
require 'securerandom'
require 'json'
require 'time'

module Firmware
  module Auth
    class RateLimiter
      WINDOW_SIZE = 300  # 5 minute window
      MAX_ATTEMPTS = 5

      def initialize(store)
        @store = store
      end

      def check_rate_limit(identifier)
        key = "rate:#{identifier}"
        window_start = Time.now.to_i - WINDOW_SIZE
        @store.cleanup_before(key, window_start)
        attempts = @store.count(key)
        attempts < MAX_ATTEMPTS
      end

      def record_attempt(identifier)
        key = "rate:#{identifier}"
        @store.append(key, Time.now.to_i)
      end
    end

    class CredentialValidator
      BCRYPT_COST = 12

      def initialize(device_registry)
        @registry = device_registry
      end

      def validate(device_id, credential)
        stored = @registry.get_credential(device_id)
        return false unless stored
        timing_safe_compare(stored, hash_credential(credential, stored[:salt]))
      end

      private

      def hash_credential(credential, salt)
        # Use PBKDF2 with device-specific salt
        OpenSSL::PKCS5.pbkdf2_hmac(
          credential, salt, 100_000, 32, 'sha256'
        ).unpack1('H*')
      end

      def timing_safe_compare(a, b)
        return false unless a[:hash].bytesize == b.bytesize
        result = 0
        a[:hash].bytes.zip(b.bytes) { |x, y| result |= x ^ y }
        result == 0
      end
    end

    class AuthController
      def initialize(config: nil)
        @config = config || load_config
        @rate_limiter = RateLimiter.new(MemoryStore.new)
        @validator = CredentialValidator.new(DeviceRegistry.new(@config))
        @session_manager = SessionManager.new(@config)
        @audit_log = AuditLog.new(@config)
      end

      def authenticate(request)
        device_id = request[:device_id]
        credential = request[:credential]
        source_ip = request[:source_ip]

        # Input validation
        return error_response(:invalid_input) unless valid_input?(device_id, credential)

        # Determine rate limit identifier based on deployment mode
        rate_id = compute_rate_identifier(device_id, source_ip)

        # Check rate limit
        unless @rate_limiter.check_rate_limit(rate_id)
          @audit_log.log(:rate_limited, device_id: device_id, ip: source_ip)
          return error_response(:rate_limited)
        end

        # Record this attempt
        @rate_limiter.record_attempt(rate_id)

        # Validate credentials
        if @validator.validate(device_id, credential)
          @audit_log.log(:auth_success, device_id: device_id)
          token = @session_manager.create_session(device_id)
          success_response(token)
        else
          @audit_log.log(:auth_failure, device_id: device_id, ip: source_ip)
          error_response(:invalid_credentials)
        end
      end

      private

      def compute_rate_identifier(device_id, source_ip)
        # Always rate limit using composite key of both device_id AND source_ip
        # to prevent credential stuffing regardless of deployment configuration.
        # This ensures an attacker cannot bypass rate limiting by varying either
        # the device_id or the source IP independently.
        "#{device_id}:#{source_ip}"
      end

      def valid_input?(device_id, credential)
        return false if device_id.nil? || credential.nil?
        return false unless device_id.is_a?(String) && credential.is_a?(String)
        return false unless device_id.match?(/\A[a-zA-Z0-9\-]{8,64}\z/)
        return false if credential.length > 256
        true
      end

      def load_config
        mode = ENV.fetch('FIRMWARE_DEPLOYMENT_MODE', 'standalone')
        {
          deployment_mode: mode,
          max_sessions: ENV.fetch('MAX_SESSIONS', '100').to_i,
          session_ttl: ENV.fetch('SESSION_TTL', '3600').to_i
        }
      end

      def error_response(code)
        { success: false, error: code }
      end

      def success_response(token)
        { success: true, token: token }
      end
    end

    class MemoryStore
      def initialize
        @data = {}
        @mutex = Mutex.new
      end

      def append(key, value)
        @mutex.synchronize do
          @data[key] ||= []
          @data[key] << value
        end
      end

      def count(key)
        @mutex.synchronize do
          (@data[key] || []).length
        end
      end

      def cleanup_before(key, timestamp)
        @mutex.synchronize do
          return unless @data[key]
          @data[key].reject! { |t| t < timestamp }
        end
      end
    end
  end
end
